/**
 * Cartograph Phase 10 — Gate 10F
 * Backend-to-React-Flow Transformation Utility
 *
 * Guarantees:
 * 1. Backend node.id is preserved byte-for-byte as React Flow node.id.
 * 2. Backend edge.id is preserved byte-for-byte as React Flow edge.id.
 * 3. Direction (source -> target) is strictly preserved; never inverted.
 * 4. Only explicitly confirmed backend edges are rendered (fails closed).
 * 5. Ambiguous, unresolved, dynamic, unsupported, and unconfirmed records
 *    never become React Flow dependency edges.
 * 6. No synthetic nodes or edges are generated by client-side inference.
 */

export const NODE_TYPES = {
  FILE: 'file',
  SYMBOL: 'symbol',
  EXTERNAL: 'external',
}

const REJECTED_STATUSES = new Set([
  'ambiguous',
  'unresolved',
  'dynamic',
  'unsupported',
  'not_attempted',
  'unconfirmed',
  'pending',
  'failed',
])

/**
 * Authoritatively verifies whether a graph edge is confirmed.
 * Fails closed on missing, ambiguous, or unconfirmed metadata.
 *
 * @param {object} backendEdge
 * @returns {boolean} True if and only if the edge is authoritatively confirmed.
 */
export function isEdgeConfirmed(backendEdge) {
  if (!backendEdge || typeof backendEdge !== 'object') {
    return false
  }

  // 1. Explicit negative confirmation flags must strictly fail
  if (backendEdge.confirmed === false || backendEdge.isConfirmed === false) {
    return false
  }

  // 2. Reject unconfirmed string statuses at the edge level
  const rawStatus = String(backendEdge.status || '').toLowerCase().trim()
  if (rawStatus && REJECTED_STATUSES.has(rawStatus)) {
    return false
  }

  // 3. Reject non-boolean values for confirmed / isConfirmed (e.g. 'ambiguous', null, numbers)
  if (backendEdge.confirmed !== undefined && typeof backendEdge.confirmed !== 'boolean') {
    return false
  }
  if (backendEdge.isConfirmed !== undefined && typeof backendEdge.isConfirmed !== 'boolean') {
    return false
  }

  // 4. Authoritative explicit boolean confirmation at edge level
  if (backendEdge.confirmed === true || backendEdge.isConfirmed === true) {
    return true
  }

  // 5. Evidence-level verification (GraphBuilder / GraphValidator normalized evidence)
  if (Array.isArray(backendEdge.evidence) && backendEdge.evidence.length > 0) {
    const hasConfirmedEvidence = backendEdge.evidence.some(
      (ev) =>
        ev &&
        ev.status &&
        (ev.status.isConfirmed === true || ev.status.confirmed === true),
    )

    const hasRejectedEvidence = backendEdge.evidence.some((ev) => {
      if (!ev || !ev.status) return true // missing status in evidence fails closed
      if (ev.status.isConfirmed === false || ev.status.confirmed === false) return true
      const norm = String(ev.status.normalized || '').toLowerCase()
      const orig = String(ev.status.original || '').toLowerCase()
      return REJECTED_STATUSES.has(norm) || REJECTED_STATUSES.has(orig)
    })

    if (hasConfirmedEvidence && !hasRejectedEvidence) {
      return true
    }
  }

  // 6. Fail closed on missing, incomplete, or ambiguous confirmation metadata
  return false
}

export function formatNodeLabel(node) {
  if (!node) return ''
  if (node.type === NODE_TYPES.FILE) {
    if (node.path) {
      const parts = node.path.split('/')
      return parts[parts.length - 1] || node.path
    }
    return node.id
  }
  if (node.type === NODE_TYPES.SYMBOL) {
    return node.name || node.qualifiedName || node.id
  }
  if (node.type === NODE_TYPES.EXTERNAL) {
    return node.packageName || node.id
  }
  return node.id
}

export function transformNode(backendNode) {
  if (!backendNode || typeof backendNode.id !== 'string') {
    throw new Error('Invalid backend node: missing string id')
  }

  const rawType = (backendNode.type || 'file').toLowerCase()
  const flowType =
    rawType === 'symbol'
      ? NODE_TYPES.SYMBOL
      : rawType === 'external'
      ? NODE_TYPES.EXTERNAL
      : NODE_TYPES.FILE

  const label = formatNodeLabel(backendNode)

  return {
    id: backendNode.id, // Strictly canonical ID preserved byte-for-byte
    type: flowType,
    position: { x: 0, y: 0 }, // Assigned by layout engine
    data: {
      canonicalId: backendNode.id,
      label,
      rawType: backendNode.type,
      path: backendNode.path || null,
      name: backendNode.name || null,
      qualifiedName: backendNode.qualifiedName || null,
      kind: backendNode.kind || null,
      language: backendNode.language || null,
      ecosystem: backendNode.ecosystem || null,
      packageName: backendNode.packageName || null,
      versionRequirement: backendNode.versionRequirement || null,
      range: backendNode.range || null,
      fileNodeId: backendNode.fileNodeId || null,
      rawNode: backendNode,
    },
  }
}

export function transformEdge(backendEdge) {
  if (!backendEdge || typeof backendEdge.id !== 'string') {
    throw new Error('Invalid backend edge: missing string id')
  }
  if (!backendEdge.source || !backendEdge.target) {
    throw new Error(`Invalid backend edge ${backendEdge.id}: missing source or target`)
  }

  // Strictly fail closed if the edge is not explicitly confirmed
  if (!isEdgeConfirmed(backendEdge)) {
    return null
  }

  const evidenceCount =
    backendEdge.evidenceCount !== undefined
      ? backendEdge.evidenceCount
      : Array.isArray(backendEdge.evidence)
      ? backendEdge.evidence.length
      : 1

  return {
    id: backendEdge.id, // Strictly canonical ID preserved byte-for-byte
    source: backendEdge.source, // Strictly preserved direction
    target: backendEdge.target, // Strictly preserved direction
    type: 'smoothstep',
    data: {
      canonicalId: backendEdge.id,
      edgeType: backendEdge.type || 'depends_on',
      evidenceCount,
      confirmed: true,
      rawEdge: backendEdge,
    },
  }
}

/**
 * Transforms an array of backend nodes and edges into React Flow structures.
 * Performs deduplication while guaranteeing strict canonical ID preservation.
 */
export function transformGraphToFlowElements(backendData = {}) {
  const rawNodes = Array.isArray(backendData.nodes) ? backendData.nodes : []
  const rawEdges = Array.isArray(backendData.edges) ? backendData.edges : []

  const nodeMap = new Map()
  for (const rawNode of rawNodes) {
    if (rawNode && rawNode.id && !nodeMap.has(rawNode.id)) {
      nodeMap.set(rawNode.id, transformNode(rawNode))
    }
  }

  const edgeMap = new Map()
  for (const rawEdge of rawEdges) {
    if (rawEdge && rawEdge.id && !edgeMap.has(rawEdge.id)) {
      const flowEdge = transformEdge(rawEdge)
      if (flowEdge) {
        edgeMap.set(flowEdge.id, flowEdge)
      }
    }
  }

  return {
    nodes: Array.from(nodeMap.values()),
    edges: Array.from(edgeMap.values()),
    truncated: Boolean(backendData.truncated),
  }
}

/**
 * Applies visual highlight tones to edges based on selected node and selected edge.
 */
export function applyGraphSelectionTones(edges, selectedNodeId, selectedEdgeId) {
  if (!selectedNodeId && !selectedEdgeId) {
    return edges.map((edge) => ({
      ...edge,
      selected: false,
      tone: 'default',
    }))
  }

  return edges.map((edge) => {
    const isSelectedEdge = edge.id === selectedEdgeId
    const isOutgoing = selectedNodeId && edge.source === selectedNodeId
    const isIncoming = selectedNodeId && edge.target === selectedNodeId

    let tone = 'default'
    if (selectedEdgeId) {
      tone = isSelectedEdge ? 'outgoing' : 'dim'
    } else if (selectedNodeId) {
      if (isOutgoing) tone = 'outgoing'
      else if (isIncoming) tone = 'incoming'
      else tone = 'dim'
    }

    return {
      ...edge,
      selected: isSelectedEdge,
      tone,
    }
  })
}
